import{_ as t,o,c as a,a2 as n}from"./chunks/framework.CHeM0PsO.js";const h=JSON.parse('{"title":"Lesson 5: Installing Codex Desktop App (Step-by-Step)","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/module-2/lesson-5.md","filePath":"en/modules/module-2/lesson-5.md"}'),i={name:"en/modules/module-2/lesson-5.md"};function s(l,e,r,d,p,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="lesson-5-installing-codex-desktop-app-step-by-step" tabindex="-1">Lesson 5: Installing Codex Desktop App (Step-by-Step) <a class="header-anchor" href="#lesson-5-installing-codex-desktop-app-step-by-step" aria-label="Permalink to &quot;Lesson 5: Installing Codex Desktop App (Step-by-Step)&quot;">​</a></h1><blockquote><p>📌 <strong>Learning Objectives</strong>: Successfully install and log into the Codex desktop app on your computer ⏱️ <strong>Estimated Time</strong>: 15 minutes 🎯 <strong>Teaching Rhythm</strong>: Step-by-step demo + hands-on practice</p></blockquote><hr><h2 id="i-download-and-install" tabindex="-1">I. Download and Install <a class="header-anchor" href="#i-download-and-install" aria-label="Permalink to &quot;I. Download and Install&quot;">​</a></h2><h3 id="macos-users" tabindex="-1">macOS Users <a class="header-anchor" href="#macos-users" aria-label="Permalink to &quot;macOS Users&quot;">​</a></h3><ol><li>Open your browser and visit the ChatGPT website: <a href="https://chatgpt.com" target="_blank" rel="noreferrer">https://chatgpt.com</a></li><li>After logging in, find the <strong>&quot;Codex&quot;</strong> or <strong>&quot;Code Interpreter&quot;</strong> entry in the left menu</li><li>Click and select &quot;Download Desktop App&quot; (if available)</li><li>After downloading, drag the app into your &quot;Applications&quot; folder</li><li>When opening for the first time, the system may warn &quot;from an unidentified developer.&quot; Go to &quot;System Preferences → Security &amp; Privacy&quot; and allow it.</li></ol><h3 id="windows-users" tabindex="-1">Windows Users <a class="header-anchor" href="#windows-users" aria-label="Permalink to &quot;Windows Users&quot;">​</a></h3><ol><li>Open your browser and visit the ChatGPT website: <a href="https://chatgpt.com" target="_blank" rel="noreferrer">https://chatgpt.com</a></li><li>After logging in, find the <strong>&quot;Codex&quot;</strong> or <strong>&quot;Code Interpreter&quot;</strong> entry in the left menu</li><li>Click and select &quot;Download Desktop App&quot; (if available)</li><li>After downloading, double-click the installer</li><li>Follow the installation wizard prompts to complete the installation.</li></ol><blockquote><p>⚠️ <strong>Important</strong>: Only download from the official OpenAI entry point. Do not download from third-party websites.</p></blockquote><hr><h2 id="ii-log-in" tabindex="-1">II. Log In <a class="header-anchor" href="#ii-log-in" aria-label="Permalink to &quot;II. Log In&quot;">​</a></h2><ol><li>Open the Codex desktop app</li><li>Log in with your ChatGPT account</li><li>If you&#39;re using a Plus/Pro account, you can access advanced features immediately after logging in.</li></ol><blockquote><p>💡 <strong>Tip</strong>: If you don&#39;t have a ChatGPT account yet, please sign up first. The registration process is simple — just an email address or phone number is enough.</p></blockquote><hr><h2 id="iii-verify-installation" tabindex="-1">III. Verify Installation <a class="header-anchor" href="#iii-verify-installation" aria-label="Permalink to &quot;III. Verify Installation&quot;">​</a></h2><p>After successful installation, you should see the Codex main interface. If you can&#39;t see it, check:</p><ul><li>Is your network connection working?</li><li>Are you logged into your ChatGPT account?</li><li>Are you running the latest version of Codex?</li></ul><hr><h2 id="iv-in-lesson-practice-tasks" tabindex="-1">IV. In-Lesson Practice Tasks <a class="header-anchor" href="#iv-in-lesson-practice-tasks" aria-label="Permalink to &quot;IV. In-Lesson Practice Tasks&quot;">​</a></h2><ol><li>Follow the steps above to install Codex</li><li>Log into your ChatGPT account</li><li>Confirm you can see the Codex main interface.</li></ol><blockquote><p>💡 <strong>Tip</strong>: If you encounter issues during installation, refer to the <a href="./../../appendix/faq.html">FAQ</a>.</p></blockquote><hr><h2 id="v-next-step" tabindex="-1">V. Next Step <a class="header-anchor" href="#v-next-step" aria-label="Permalink to &quot;V. Next Step&quot;">​</a></h2><p><a href="./lesson-6.html">→ Lesson 6: Understanding the Codex Interface</a></p>',24)])])}const g=t(i,[["render",s]]);export{h as __pageData,g as default};
